// ---- UAT 138: Cat Jam v4 (CP-104, the CP-96 engineer; Jenny: "put it in Daily puzzles in the next UAT build (138)") ----
// The page is work/cp104-cat-jam/cat-jam-v4.html byte for byte (one self-contained file, like Sleepy Coins), listed in the Daily
// puzzles menu. Nothing else in the game changes.
CP87_PAGES['cat-jam']="<!doctype html>\r\n<html lang=\"en\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no,viewport-fit=cover\">\r\n<title>Cat Jam<\/title>\r\n<style>\r\nhtml,body{margin:0;height:100%;background:#140b26;overflow:hidden;touch-action:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent}\r\ncanvas{display:block;width:100vw;height:100vh;height:100dvh}\r\n<\/style>\r\n<\/head>\r\n<body>\r\n<canvas id=\"cv\"><\/canvas>\r\n<script>\r\n'use strict';\r\n// CP-104 Cat Jam v4 (daily puzzle; drop-in page for the Daily puzzles menu). Cats drawn in code (cat-sheet.html); treats are CatCoin's approved art, as is.\r\n// Self-contained: no network, no host calls; its only saved setting is catjam.muted. Works full screen or in the menu's frame.\r\nconst ART={\"biscuit\": \"data:image/webp;base64,\", \"cheese\": \"data:image/webp;base64,\", \"sardine\": \"data:image/webp;base64,\", \"shrimp\": \"data:image/webp;base64,\", \"tuna\": \"data:image/webp;base64,\"};\r\nconst BOARDS=[{\"name\":\"Warm-up\",\"cols\":4,\"rows\":5,\"cats\":[{\"c\":2,\"r\":1,\"d\":3,\"k\":1},{\"c\":3,\"r\":3,\"d\":2,\"k\":1},{\"c\":2,\"r\":2,\"d\":3,\"k\":2},{\"c\":1,\"r\":3,\"d\":2,\"k\":2},{\"c\":1,\"r\":1,\"d\":0,\"k\":1},{\"c\":1,\"r\":4,\"d\":3,\"k\":0},{\"c\":0,\"r\":2,\"d\":0,\"k\":0},{\"c\":2,\"r\":3,\"d\":3,\"k\":0},{\"c\":0,\"r\":1,\"d\":3,\"k\":2},{\"c\":3,\"r\":1,\"d\":2,\"k\":0},{\"c\":2,\"r\":4,\"d\":3,\"k\":1},{\"c\":1,\"r\":2,\"d\":0,\"k\":0},{\"c\":0,\"r\":3,\"d\":2,\"k\":2},{\"c\":2,\"r\":0,\"d\":1,\"k\":0},{\"c\":1,\"r\":0,\"d\":1,\"k\":2},{\"c\":3,\"r\":2,\"d\":2,\"k\":1}],\"plates\":[1,1,1,2,2,0,2,0,0,0,0,0,0,1,0,1,0,1,0,1,1,1,2,2,0,0,2,2,2,2,2,0,1,1,1,2,2,0,0,0,1,1,0,0,2,1,2,2]},{\"name\":\"Lunch rush\",\"cols\":4,\"rows\":5,\"cats\":[{\"c\":2,\"r\":0,\"d\":3,\"k\":2},{\"c\":1,\"r\":2,\"d\":0,\"k\":2},{\"c\":1,\"r\":3,\"d\":2,\"k\":1},{\"c\":0,\"r\":2,\"d\":0,\"k\":1},{\"c\":3,\"r\":3,\"d\":2,\"k\":1},{\"c\":3,\"r\":0,\"d\":0,\"k\":0},{\"c\":3,\"r\":1,\"d\":0,\"k\":1},{\"c\":2,\"r\":1,\"d\":0,\"k\":0},{\"c\":1,\"r\":0,\"d\":0,\"k\":2},{\"c\":0,\"r\":0,\"d\":0,\"k\":0},{\"c\":3,\"r\":2,\"d\":0,\"k\":1},{\"c\":0,\"r\":3,\"d\":2,\"k\":2},{\"c\":0,\"r\":1,\"d\":0,\"k\":2},{\"c\":1,\"r\":1,\"d\":3,\"k\":1},{\"c\":1,\"r\":4,\"d\":3,\"k\":2},{\"c\":2,\"r\":3,\"d\":3,\"k\":0},{\"c\":2,\"r\":2,\"d\":2,\"k\":0},{\"c\":2,\"r\":4,\"d\":1,\"k\":0}],\"plates\":[2,2,2,2,0,2,0,2,0,0,2,1,2,2,1,0,0,1,2,0,0,0,1,1,1,0,2,2,2,0,0,1,2,1,1,1,1,1,2,0,0,1,1,1,0,2,2,2,1,0,1,0,0,1]},{\"name\":\"Full house\",\"cols\":5,\"rows\":5,\"cats\":[{\"c\":1,\"r\":3,\"d\":2,\"k\":3},{\"c\":2,\"r\":0,\"d\":1,\"k\":0},{\"c\":4,\"r\":3,\"d\":2,\"k\":2},{\"c\":0,\"r\":3,\"d\":3,\"k\":1},{\"c\":2,\"r\":4,\"d\":1,\"k\":3},{\"c\":2,\"r\":2,\"d\":0,\"k\":3},{\"c\":3,\"r\":4,\"d\":1,\"k\":1},{\"c\":1,\"r\":1,\"d\":3,\"k\":3},{\"c\":0,\"r\":4,\"d\":2,\"k\":2},{\"c\":3,\"r\":3,\"d\":2,\"k\":1},{\"c\":0,\"r\":1,\"d\":0,\"k\":2},{\"c\":2,\"r\":1,\"d\":3,\"k\":2},{\"c\":1,\"r\":4,\"d\":3,\"k\":1},{\"c\":1,\"r\":0,\"d\":3,\"k\":2},{\"c\":0,\"r\":2,\"d\":0,\"k\":0},{\"c\":3,\"r\":2,\"d\":2,\"k\":1},{\"c\":3,\"r\":1,\"d\":0,\"k\":3},{\"c\":1,\"r\":2,\"d\":1,\"k\":0},{\"c\":4,\"r\":2,\"d\":2,\"k\":1},{\"c\":2,\"r\":3,\"d\":3,\"k\":0},{\"c\":4,\"r\":4,\"d\":2,\"k\":0},{\"c\":4,\"r\":1,\"d\":0,\"k\":0}],\"plates\":[3,3,0,2,3,0,2,2,0,0,2,0,2,1,2,0,2,2,0,2,0,2,1,2,1,0,3,1,3,3,0,1,2,1,0,0,1,1,1,1,3,3,1,1,3,1,1,3,3,3,1,3,1,0,3,1,1,3,2,2,2,0,0,0,0,0]},{\"name\":\"Mixed plates\",\"cols\":5,\"rows\":6,\"cats\":[{\"c\":1,\"r\":5,\"d\":3,\"k\":3},{\"c\":2,\"r\":2,\"d\":1,\"k\":1},{\"c\":3,\"r\":5,\"d\":2,\"k\":2},{\"c\":3,\"r\":3,\"d\":2,\"k\":2},{\"c\":1,\"r\":1,\"d\":1,\"k\":3},{\"c\":1,\"r\":0,\"d\":0,\"k\":0},{\"c\":3,\"r\":0,\"d\":1,\"k\":0},{\"c\":2,\"r\":0,\"d\":3,\"k\":0},{\"c\":1,\"r\":2,\"d\":0,\"k\":1},{\"c\":0,\"r\":0,\"d\":3,\"k\":2},{\"c\":4,\"r\":3,\"d\":0,\"k\":1},{\"c\":2,\"r\":4,\"d\":1,\"k\":1},{\"c\":0,\"r\":2,\"d\":2,\"k\":1},{\"c\":3,\"r\":2,\"d\":2,\"k\":3},{\"c\":1,\"r\":3,\"d\":0,\"k\":1},{\"c\":0,\"r\":3,\"d\":2,\"k\":0},{\"c\":3,\"r\":1,\"d\":1,\"k\":0},{\"c\":3,\"r\":4,\"d\":2,\"k\":3},{\"c\":4,\"r\":2,\"d\":0,\"k\":0},{\"c\":0,\"r\":1,\"d\":0,\"k\":2},{\"c\":4,\"r\":1,\"d\":0,\"k\":1},{\"c\":2,\"r\":1,\"d\":0,\"k\":2},{\"c\":2,\"r\":3,\"d\":0,\"k\":3},{\"c\":0,\"r\":4,\"d\":2,\"k\":0},{\"c\":2,\"r\":5,\"d\":3,\"k\":2},{\"c\":1,\"r\":4,\"d\":2,\"k\":3}],\"plates\":[0,0,0,3,2,3,2,3,2,3,3,3,0,0,0,3,3,3,2,0,1,1,1,2,2,0,0,2,2,2,2,0,2,0,0,1,1,1,2,2,2,3,2,1,1,1,3,0,0,2,0,0,0,2,0,3,2,0,0,0,1,1,1,3,1,1,3,1,1,3,1,1,3,1,3,1,3,1]},{\"name\":\"Big jam\",\"cols\":5,\"rows\":6,\"cats\":[{\"c\":3,\"r\":3,\"d\":2,\"k\":0},{\"c\":4,\"r\":4,\"d\":2,\"k\":3},{\"c\":1,\"r\":0,\"d\":0,\"k\":2},{\"c\":4,\"r\":2,\"d\":2,\"k\":3},{\"c\":0,\"r\":0,\"d\":0,\"k\":1},{\"c\":1,\"r\":4,\"d\":3,\"k\":1},{\"c\":1,\"r\":5,\"d\":3,\"k\":0},{\"c\":4,\"r\":5,\"d\":2,\"k\":2},{\"c\":2,\"r\":4,\"d\":3,\"k\":4},{\"c\":2,\"r\":2,\"d\":1,\"k\":1},{\"c\":0,\"r\":2,\"d\":2,\"k\":0},{\"c\":0,\"r\":5,\"d\":2,\"k\":2},{\"c\":3,\"r\":2,\"d\":2,\"k\":0},{\"c\":4,\"r\":3,\"d\":2,\"k\":3},{\"c\":2,\"r\":0,\"d\":3,\"k\":2},{\"c\":2,\"r\":1,\"d\":3,\"k\":4},{\"c\":1,\"r\":3,\"d\":2,\"k\":3},{\"c\":0,\"r\":1,\"d\":3,\"k\":1},{\"c\":0,\"r\":3,\"d\":2,\"k\":4},{\"c\":3,\"r\":0,\"d\":3,\"k\":0},{\"c\":4,\"r\":1,\"d\":0,\"k\":1},{\"c\":1,\"r\":2,\"d\":2,\"k\":4},{\"c\":3,\"r\":5,\"d\":1,\"k\":4},{\"c\":1,\"r\":1,\"d\":3,\"k\":2},{\"c\":3,\"r\":1,\"d\":0,\"k\":0},{\"c\":2,\"r\":3,\"d\":3,\"k\":1},{\"c\":0,\"r\":4,\"d\":2,\"k\":3},{\"c\":2,\"r\":5,\"d\":1,\"k\":2}],\"plates\":[2,2,1,1,4,2,1,4,0,2,4,1,2,1,1,1,2,2,2,1,1,0,0,2,2,3,2,2,2,3,3,2,2,4,4,0,4,0,0,0,0,0,4,4,4,2,3,0,0,2,2,0,0,3,0,0,3,1,1,4,1,4,4,3,3,3,3,3,3,0,1,1,1,0,4,4,4,0,1,3,3,1,3,1]}];\r\nconst W=400;\r\nconst CATART=(()=>{\r\n// ---------- the cat ----------\r\n// Drawn like the dashboard's pigeons: one smooth outline per part, filled, with soft light and shade blended inside it (clipped),\r\n// a few fine detail lines, and only a faint edge. Feet at (0,0); about 50 units tall sitting, 46 long walking, at s = 1.\r\nconst COATS=[\r\n {name:'Ginger',base:'#e98f3c',light:'#f8b871',dark:'#b65d1c',belly:'#fbe6c8',stripe:'rgba(150,62,14,.6)',eye:'#8cc63f',nose:'#e88a96',collar:'#3f8cff'},\r\n {name:'Grey',base:'#8e96a2',light:'#b7bec8',dark:'#5f6773',belly:'#eef0f2',stripe:'rgba(62,68,80,.6)',eye:'#e9b43a',nose:'#d98a98',collar:'#ff4f8a'},\r\n {name:'Tuxedo',base:'#2a272e',light:'#55505d',dark:'#151318',belly:'#f6f3ec',stripe:null,eye:'#d9cc3a',nose:'#e88a9a',collar:'#ff3b3b',darkCoat:true,tux:true}, // Jenny, Nov 20: a tuxedo (white face, chest, paws, belly)\r\n {name:'Ragdoll',base:'#f0d9b2',light:'#fbefdc',dark:'#cfab7c',belly:'#fffaf2',stripe:'rgba(196,140,82,.5)',eye:'#d58f2f',nose:'#ec98a4',collar:'#2fbf5a',floof:true}, // Jenny, Nov 20: the cream cat she liked, floofier by body shape (no tufts, no points)\r\n {name:'Calico',base:'#f7f1e7',light:'#ffffff',dark:'#d3c8b9',belly:'#ffffff',stripe:null,eye:'#97c14a',nose:'#ea96a2',collar:'#a64dff',calico:{o:'#e2853a',k:'#2c282f'}}];\r\nlet c=null; // the 2d context being drawn on\r\nconst EDGE='rgba(52,30,16,.42)';\r\nfunction ell(x,y,rx,ry,rot,fill){c.fillStyle=fill;c.beginPath();c.ellipse(x,y,rx,ry,rot,0,7);c.fill();}\r\nfunction soft(x,y,r,col,a){const g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,col);g.addColorStop(.55,col);g.addColorStop(1,'rgba(0,0,0,0)');c.globalAlpha=a;c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2);c.globalAlpha=1;}\r\n// soft2: like soft, but fades to the same colour, clear (no grey halo); used for the floofy cat's white chest\r\nfunction soft2(x,y,r,hex,a){const n=parseInt(hex.slice(1),16),rgb=(n>>16)+','+(n>>8&255)+','+(n&255),g=c.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(${rgb},${a})`);g.addColorStop(.55,`rgba(${rgb},${a*.85})`);g.addColorStop(1,`rgba(${rgb},0)`);c.fillStyle=g;c.fillRect(x-r,y-r,r*2,r*2);}\r\nfunction inside(path,fn){c.save();path();c.clip();fn();c.restore();}\r\nfunction edge(path,w=.8){path();c.lineWidth=w;c.strokeStyle=EDGE;c.stroke();}\r\nfunction ln(pts,col,w){c.beginPath();c.moveTo(pts[0],pts[1]);for(let i=2;i<pts.length;i+=2)c.lineTo(pts[i],pts[i+1]);c.strokeStyle=col;c.lineWidth=w;c.stroke();}\r\nfunction curve(x0,y0,cx,cy,x1,y1,col,w){c.beginPath();c.moveTo(x0,y0);c.quadraticCurveTo(cx,cy,x1,y1);c.strokeStyle=col;c.lineWidth=w;c.stroke();}\r\nfunction tube(pts,w0,w1,col,edged=true){ // a tapering tail or leg: a quadratic spine drawn as overlapping round dabs, edge first\r\n const [x0,y0,cx,cy,x1,y1]=pts;for(const pass of edged?[0,1]:[1])for(let i=0;i<=28;i++){const u=i/28,a=(1-u)*(1-u),b=2*u*(1-u),d=u*u,r=(w0+(w1-w0)*u)/2+(pass?0:.5);ell(a*x0+b*cx+d*x1,a*y0+b*cy+d*y1,r,r,0,pass?col:EDGE);}}\r\nfunction tubeEdge(){}\r\n// fur: a tuft is a soft teardrop from (x,y) pointing at angle a; a fringe draws a row of them with one faint edge round the lot\r\nfunction tuftPath(x,y,a,len,w){const ca=Math.cos(a),sa=Math.sin(a),nx=-sa*w/2,ny=ca*w/2,ex=x+ca*len,ey=y+sa*len;c.beginPath();c.moveTo(x+nx,y+ny);\r\n c.bezierCurveTo(x+nx*1.05+ca*len*.55,y+ny*1.05+sa*len*.55,ex+nx*.55,ey+ny*.55,ex,ey);c.bezierCurveTo(ex-nx*.55,ey-ny*.55,x-nx*1.05+ca*len*.55,y-ny*1.05+sa*len*.55,x-nx,y-ny);c.closePath();} // soft, round-tipped\r\nfunction fringe(list,col,edged=true){if(edged)for(const t of list){tuftPath(...t);c.lineWidth=.9;c.strokeStyle=EDGE;c.stroke();}for(const t of list){tuftPath(...t);c.fillStyle=col;c.fill();}}\r\nfunction tailDraw(TP,w0,w1,C,K){if(!C.fluffy){tube(TP,w0,w1,K?K.k:C.base);return;}\r\n const [x0,y0,cx,cy,x1,y1]=TP,col=C.points?mix(C.base,C.points,.55):C.base,P=u=>{const a=(1-u)*(1-u),b=2*u*(1-u),d=u*u;return [a*x0+b*cx+d*x1,a*y0+b*cy+d*y1];},list=[];\r\n for(let i=1;i<=11;i++){const u=i/12,[px,py]=P(u),[qx,qy]=P(Math.min(1,u+.04)),ang=Math.atan2(qy-py,qx-px),w=(w0+(w1-w0)*u)*.75;\r\n  for(const sd of [-1,1])list.push([px,py,ang+sd*(Math.PI/2+.55),w*.85+(i%2)*.5,w*1.5]);}\r\n list.push([...P(1),Math.atan2(y1-P(.95)[1],x1-P(.95)[0]),2.8,5.2]);\r\n fringe(list,col);tube(TP,w0*1.45,w1*1.7,col);\r\n c.save();c.globalAlpha=.45;for(const off of [-.8,.8]){c.beginPath();for(let i=2;i<=10;i++){const [px,py]=P(i/12);c[i===2?'moveTo':'lineTo'](px+off,py+off*.3);}c.strokeStyle=C.light;c.lineWidth=.35;c.stroke();}c.restore();}\r\nfunction fluffBody(kind,C){const L=[];\r\n if(kind==='walk'){for(let i=0;i<6;i++)L.push([-10+i*3.4,-8.6,Math.PI/2+(i%2?.12:-.12),2.6+(i%2)*.6,5.4]);L.push([-16.4,-11.2,Math.PI*.76,3.4,5.6],[-15.2,-9.2,Math.PI*.66,3,5]);fringe(L,C.light);\r\n  fringe([[-14,-17.6,-Math.PI*.62,2.6,3.4],[-8,-19.6,-Math.PI*.55,2.2,3.2]],C.base);return;}\r\n for(let i=0;i<5;i++){const t=i/4,y=-21+t*17,x=11.2+t*4,l=2.4+t*1+(i%2)*.7,w=6+(i%2);L.push([-x,y,Math.PI-.75+t*.15,l,w],[x,y,.75-t*.15,l,w]);}fringe(L,C.base);}\r\nfunction ruff(C,eat){const L1=[],L2=[],dy=eat*1.5;for(let i=0;i<=8;i++){const u=i/8,x=-10.5+u*21,y=-26+Math.sin(u*Math.PI)*1.5+dy;L1.push([x,y,Math.PI/2+(u-.5)*1.3,6.4-Math.abs(u-.5)*4.4,6.6]);}\r\n for(let i=0;i<=6;i++){const u=i/6,x=-7.5+u*15,y=-25+dy;L2.push([x,y,Math.PI/2+(u-.5)*.9,4.6-Math.abs(u-.5)*2.6,6]);}\r\n fringe(L1,C.belly);fringe(L2,C.belly,false);c.save();c.globalAlpha=.35;for(const t of L1){const [x,y,a,l]=t;ln([x,y+1,x+Math.cos(a)*l*.8,y+Math.sin(a)*l*.8],C.dark,.35);}c.restore();}\r\n\r\nfunction limb(x0,y0,x1,y1,w0,w1,col,edged=true){tube([x0,y0,(x0+x1)/2,(y0+y1)/2,x1,y1],w0,w1,col,edged);}\r\nfunction eye(x,y,w,h,C,o){ // almond eye: iris with a lighter middle, slit pupil, a shine; closed = a happy curve; lid = half shut\r\n if(o.happy){c.lineCap='round';curve(x-w,y+.3,x,y-h*1.25,x+w,y+.3,C.darkCoat?'#0b0a0c':'#3a2414',.75);return;}\r\n const al=()=>{c.beginPath();c.moveTo(x-w,y+.15);c.quadraticCurveTo(x-.1,y-h*1.15,x+w,y-.2);c.quadraticCurveTo(x+.1,y+h*1.05,x-w,y+.15);c.closePath();};\r\n inside(al,()=>{const g=c.createRadialGradient(x,y+h*.2,0,x,y,w*1.1);g.addColorStop(0,'#fff6b0');g.addColorStop(.35,C.eye);g.addColorStop(1,shade(C.eye,-.35));c.fillStyle=g;c.fillRect(x-w-1,y-h-1,w*2+2,h*2+2);\r\n  ell(x+.15,y-.05,w*.27,h*.9,0,'#151216');ell(x+w*.35,y-h*.4,w*.2,w*.2,0,'#fff');\r\n  if(o.lid){c.fillStyle=C.base;c.fillRect(x-w-1,y-h-1.5,w*2+2,h*(.6+o.lid*1.2)+1);}});\r\n al();c.lineWidth=.45;c.strokeStyle=C.darkCoat?'rgba(0,0,0,.9)':'rgba(40,22,10,.8)';c.stroke();}\r\nfunction mix(a,b,k){const A=parseInt(a.slice(1),16),B=parseInt(b.slice(1),16),f=(x,y)=>Math.round(x+(y-x)*k);return `rgb(${f(A>>16,B>>16)},${f(A>>8&255,B>>8&255)},${f(A&255,B&255)})`;}\r\nfunction shade(hex,k){const n=parseInt(hex.slice(1),16);let r=n>>16,g=n>>8&255,b=n&255;const t=k<0?0:255,p=Math.abs(k);r=Math.round(r+(t-r)*p);g=Math.round(g+(t-g)*p);b=Math.round(b+(t-b)*p);return `rgb(${r},${g},${b})`;}\r\nconst WHISK=C=>C.tux?'rgba(205,205,212,.9)':C.darkCoat?'rgba(255,255,255,.75)':'rgba(70,48,32,.5)';\r\nfunction collar(x,y,w,C,bell){c.lineCap='round';curve(x-w,y-1.2,x,y+1.6,x+w,y-1.2,shade(C.collar,-.35),2.3);curve(x-w,y-1.6,x,y+1.1,x+w,y-1.6,C.collar,1.5);\r\n if(bell){ell(x,y+2.2,1.35,1.35,0,'#e7b62a');ell(x-.35,y+1.8,.45,.45,0,'#fff3b0');ln([x-1,y+2.6,x+1,y+2.6],'rgba(90,60,0,.6)',.35);}}\r\n\r\n// sitting, facing you. o: t (time, for the tail and blinks), happy, eat (0..1 head down to eat), chew (0..1)\r\nfunction catSit(cx,x,y,s,C,o={}){c=cx;c.save();c.translate(x,y);c.scale(s,s);c.lineJoin='round';c.lineCap='round';\r\n const t=o.t||0,eat=o.eat||0,K=C.calico;\r\n ell(0,.4,15,2.6,0,'rgba(60,30,10,.22)');\r\n // the tail, wrapped round the front paws, its tip lifting now and then\r\n const tip=Math.max(0,Math.sin(t*1.7))*2.2,TP=C.floof?[15,-3,9,3.6,-11,.4-tip]:[13,-2.5,7,2.6,-9,.2-tip];tailDraw(TP,C.floof?7.2:4.6,C.floof?5.8:3.2,C,K);tubeEdge(TP,4.6,3.2);\r\n if(!K){c.save();c.globalAlpha=.55;tube([2,1.2,-3,1.6,-9,.2-tip],2.4,2,C.dark);c.restore();}\r\n // body: a pear from the neck to the haunches\r\n const F=C.floof,body=()=>sitBody(F);\r\n if(C.fluffy)fluffBody('sit',C);body();c.fillStyle=C.base;c.fill();\r\n inside(body,()=>{soft(0,-23,13,C.light,.7);soft(-15,-4,9,C.dark,.38);soft(15,-4,9,C.dark,.38);soft(0,2,14,C.dark,.22);\r\n  if(K){soft(-11,-8,8,K.o,1);soft(10,-20,7,K.k,1);soft(13,-6,4.5,K.o,.9);}\r\n  if(C.stripe){c.lineCap='round';for(const sx of [-1,1]){curve(sx*14.5,-14,sx*11,-12.5,sx*10,-9.5,C.stripe,1.3);curve(sx*15.5,-9.5,sx*12,-8,sx*11.5,-5,C.stripe,1.3);curve(sx*12.5,-19,sx*10,-18,sx*9,-15.5,C.stripe,1.1);}}\r\n  if(C.belly)soft(0,-19,7.5,C.belly,.95);});\r\n edge(body);\r\n // front legs and paws\r\n const legs=()=>{c.beginPath();for(const lx of [-3.9,3.9]){c.moveTo(lx-2.7,-17);c.bezierCurveTo(lx-2.9,-10,lx-2.5,-5,lx-2.3,-1.6);c.lineTo(lx+2.3,-1.6);c.bezierCurveTo(lx+2.5,-5,lx+2.9,-10,lx+2.7,-17);c.closePath();}};\r\n legs();c.fillStyle=C.base;c.fill();inside(legs,()=>{for(const lx of [-3.9,3.9]){const g=c.createLinearGradient(lx-2.8,0,lx+2.8,0),m=C.tux?C.belly:mix(C.base,C.belly||C.light,C.belly?.55:.25),e0=C.tux?shade(C.belly,-.16):C.base,e1=C.tux?shade(C.belly,-.22):shade(C.base,-.12);g.addColorStop(0,e0);g.addColorStop(.32,m);g.addColorStop(.68,m);g.addColorStop(1,e1);c.fillStyle=g;c.fillRect(lx-3,-18,6,18);}\r\n  if(C.stripe)for(const lx of [-3.9,3.9])for(const yy of [-12,-8.5])ln([lx-2.6,yy,lx-1.2,yy+.5],C.stripe,.9);});\r\n legs();c.lineWidth=.6;c.strokeStyle=EDGE;c.stroke();\r\n for(const px of [-3.9,3.9]){ell(px,-1.4,3.2,1.9,0,C.belly||C.base);c.beginPath();c.ellipse(px,-1.4,3.2,1.9,0,0,7);c.lineWidth=.6;c.strokeStyle=EDGE;c.stroke();ln([px-1,-2.2,px-.9,-.6],'rgba(52,30,16,.4)',.4);ln([px+1,-2.2,px+.9,-.6],'rgba(52,30,16,.4)',.4);}\r\n // head (dips toward the plate when eating)\r\n if(C.fluffy)ruff(C,eat);\r\n if(F){c.save();c.translate(0,-22.5);c.scale(1.05,1.05);soft2(0,0,10.5,C.belly,1);c.restore();c.save();c.translate(0,-22.5);c.scale(1,1.2);soft2(0,0,6.5,'#ffffff',.55);c.restore();}\r\n c.save();c.translate(0,eat*3.6);head(C,{t,happy:o.happy,lid:eat>.3?.65:0,chew:o.chew||0,ears:eat*.5});c.restore();\r\n collar(0,-24.4+eat*3.6,5.6,C,true);\r\n c.restore();}\r\n// the sitting body (front and back): a pear; the floofy cat's is rounder and fuller, wider at the shoulders and haunches\r\nfunction sitBody(F){c.beginPath();if(F){c.moveTo(-11,-31.5);c.bezierCurveTo(-16.5,-28.5,-19,-20.5,-18.8,-12);c.bezierCurveTo(-19.6,-5,-17.6,.6,-11.5,.6);c.lineTo(11.5,.6);c.bezierCurveTo(17.6,.6,19.6,-5,18.8,-12);c.bezierCurveTo(19,-20.5,16.5,-28.5,11,-31.5);}\r\n else{c.moveTo(-6.5,-28);c.bezierCurveTo(-10.5,-25,-13,-19,-14,-12);c.bezierCurveTo(-16.5,-6.5,-16,-1,-11.5,0);c.lineTo(11.5,0);c.bezierCurveTo(16,-1,16.5,-6.5,14,-12);c.bezierCurveTo(13,-19,10.5,-25,6.5,-28);}c.closePath();}\r\n// the floofy cat's full neck and big soft chest (shapes, not tufts)\r\nfunction floofNeck(C){const neck=()=>{c.beginPath();c.ellipse(0,-28.2,14.8,6.8,0,0,7);};neck();c.fillStyle=C.base;c.fill();inside(neck,()=>{soft(0,-25.5,9.5,C.belly,.95);soft(-14,-28,5,C.dark,.3);soft(14,-28,5,C.dark,.3);});edge(neck,.6);}\r\nfunction floofChest(C){const ch=()=>{c.beginPath();c.moveTo(-9.8,-27);c.bezierCurveTo(-13,-21.5,-12,-14,-6.2,-12.2);c.bezierCurveTo(-2.5,-11.2,2.5,-11.2,6.2,-12.2);c.bezierCurveTo(12,-14,13,-21.5,9.8,-27);c.closePath();};\r\n ch();c.fillStyle=C.belly;c.fill();inside(ch,()=>{soft(0,-13.5,9,C.dark,.2);soft(0,-23,7,'#ffffff',.6);soft(-9,-20,4,C.base,.5);soft(9,-20,4,C.base,.5);});ch();c.lineWidth=.6;c.strokeStyle='rgba(52,30,16,.22)';c.stroke();}\r\n// the head seen from the front (centre about (0,-35))\r\nfunction head(C,o){const K=C.calico,t=o.t||0,blink=!o.happy&&((t*0.7)%3.1)<.12?1:0,eb=o.ears||0;\r\n const fc=C.floof?1.7:0;\r\n const shape=()=>{c.beginPath();c.moveTo(-11,-37);c.lineTo(-12.8+eb,-47.4+eb*1.5);c.quadraticCurveTo(-12.4+eb,-49.2+eb*1.5,-10.6+eb,-48.2+eb*1.5);c.lineTo(-4.6,-43.6);c.quadraticCurveTo(0,-45.2,4.6,-43.6);\r\n  c.lineTo(10.6-eb,-48.2+eb*1.5);c.quadraticCurveTo(12.4-eb,-49.2+eb*1.5,12.8-eb,-47.4+eb*1.5);c.lineTo(11,-37);c.bezierCurveTo(13.8+fc,-33.2,13.4+fc*1.2,-28.6+fc*.4,9.2+fc*.4,-26.4+fc*.3);c.bezierCurveTo(5,-24.3+fc*.4,-5,-24.3+fc*.4,-9.2-fc*.4,-26.4+fc*.3);c.bezierCurveTo(-13.4-fc*1.2,-28.6+fc*.4,-13.8-fc,-33.2,-11,-37);c.closePath();};\r\n if(C.fluffy)fringe([[-12.2,-31.5,Math.PI-.25,3.4,5.6],[-11.6,-28.4,Math.PI-.8,3.4,5.6],[-9.6,-26.2,Math.PI/2+.7,2.8,5],[12.2,-31.5,.25,3.4,5.6],[11.6,-28.4,.8,3.4,5.6],[9.6,-26.2,Math.PI/2-.7,2.8,5]],C.base);\r\n shape();c.fillStyle=C.base;c.fill();\r\n inside(shape,()=>{soft(0,-41,10,C.light,.6);soft(-13,-32,6,C.dark,.28);soft(13,-32,6,C.dark,.28);\r\n  if(K){soft(-9,-42,8,K.o,1);soft(9.5,-41,6.5,K.k,1);}\r\n  if(C.belly){soft(0,-29,6.2,C.belly,1);soft(-3,-28.6,3.6,C.belly,.9);soft(3,-28.6,3.6,C.belly,.9);}\r\n  if(C.points){soft(0,-34.5,8,C.points,.4);soft(0,-28,4.4,C.belly,.95);soft(0,-38.5,3.2,C.light,.4);for(const sx of [-1,1])soft(sx*11.2,-45.8,5,C.points,.85);}\r\n  if(C.tux){c.beginPath();c.moveTo(0,-39.5);c.quadraticCurveTo(1.6,-35,4,-31);c.lineTo(-4,-31);c.quadraticCurveTo(-1.6,-35,0,-39.5);c.closePath();c.fillStyle=C.belly;c.fill();soft(0,-30,6.8,C.belly,1);}\r\n  if(C.darkCoat&&!C.tux)soft(0,-29.5,5,C.light,.35);\r\n  // inner ears\r\n  for(const sx of [-1,1]){c.beginPath();c.moveTo(sx*(11.2-eb),-45.8+eb*1.5);c.lineTo(sx*(10.2-eb*.5),-39.8);c.lineTo(sx*5.8,-42.6);c.closePath();const g=c.createLinearGradient(0,-47,0,-40);g.addColorStop(0,C.darkCoat?'#6a4450':'#f2a3b2');g.addColorStop(1,C.darkCoat?'#3a2a30':shade(C.base,-.05));c.fillStyle=g;c.fill();\r\n   for(let i=0;i<3;i++)curve(sx*(6.6+i*.6),-41.6,sx*(8.6+i*.4),-43.5,sx*(9.4+i*.6),-45.2+i,'rgba(255,255,255,.55)',.3);}\r\n  if(C.stripe){c.lineCap='round';for(const [a,b,d] of [[-2.8,-42.4,-2.2],[0,-43.2,0],[2.8,-42.4,2.2]])ln([a,b,d,b+3.6],C.stripe,1);\r\n   for(const sx of [-1,1]){curve(sx*13,-33.6,sx*10.6,-33.4,sx*8.6,-32.4,C.stripe,.9);curve(sx*13,-30.8,sx*11,-30.6,sx*9.2,-29.8,C.stripe,.9);}}});\r\n edge(shape);\r\n // eyes, nose, mouth, whiskers\r\n const lid=Math.max(o.lid||0,blink);eye(-4.7,-34.4,3.5,2.9,C,{happy:o.happy,lid});eye(4.7,-34.4,3.5,2.9,C,{happy:o.happy,lid});\r\n c.beginPath();c.moveTo(-1.5,-31.3);c.lineTo(1.5,-31.3);c.quadraticCurveTo(.4,-29.4,0,-29.4);c.quadraticCurveTo(-.4,-29.4,-1.5,-31.3);c.closePath();c.fillStyle=C.nose;c.fill();ell(-.4,-30.9,.5,.25,0,'rgba(255,255,255,.5)');\r\n const mo=o.chew?Math.abs(Math.sin(o.chew*Math.PI*6))*1.4:o.happy?1:0,ink=C.darkCoat?'rgba(0,0,0,.85)':'rgba(60,34,20,.75)';\r\n ln([0,-29.4,0,-28.6],ink,.5);curve(0,-28.6,-1,-27.6,-2.3,-28.3,ink,.5);curve(0,-28.6,1,-27.6,2.3,-28.3,ink,.5);\r\n if(mo>.2){c.beginPath();c.ellipse(0,-27.4,1.2,mo*.6+.2,0,0,7);c.fillStyle='#b3485e';c.fill();}\r\n c.lineCap='round';for(const sx of [-1,1])for(const [dy,ey] of [[-.6,-1.8],[.3,.3],[1.1,2.2]])curve(sx*4.2,-29.4+dy,sx*9,-29.6+dy+ey*.4,sx*14,-29.8+ey,WHISK(C),.35);}\r\n\r\n// sitting, facing away (for cats that will walk up)\r\nfunction catBack(cx,x,y,s,C,o={}){c=cx;c.save();c.translate(x,y);c.scale(s,s);c.lineJoin='round';c.lineCap='round';const t=o.t||0,K=C.calico;\r\n ell(0,.4,15,2.6,0,'rgba(60,30,10,.22)');\r\n const F=C.floof,body=()=>sitBody(F);\r\n if(C.fluffy)fluffBody('back',C);body();c.fillStyle=C.base;c.fill();\r\n inside(body,()=>{soft(0,-22,12,C.light,.6);soft(0,2,15,C.dark,.3);soft(-15,-4,8,C.dark,.35);soft(15,-4,8,C.dark,.35);\r\n  if(K){soft(-8,-16,8,K.o,1);soft(9,-8,7,K.k,1);}\r\n  if(C.stripe){for(let i=0;i<4;i++){const yy=-23+i*5.2;curve(-9+i*.4,yy+1.6,0,yy-1,9-i*.4,yy+1.6,C.stripe,1.3);}}\r\n  ln([0,-27,0,-3],'rgba(40,24,12,.18)',.8);});\r\n edge(body);\r\n const sw=Math.sin(t*1.9)*2.2,TP=C.floof?[4,-1.5,21+sw*.4,-6,15+sw,-22]:[3,-1.5,17+sw*.4,-6,12+sw,-21];tailDraw(TP,C.floof?7.4:4.6,C.floof?6:3.3,C,K);tubeEdge(TP,4.6,3.3);\r\n if(C.stripe){c.save();c.globalAlpha=.6;for(const u of [.45,.65,.85]){const a=(1-u)*(1-u),b=2*u*(1-u),d=u*u,px=a*3+b*(17+sw*.4)+d*(12+sw),py=a*-1.5+b*-6+d*-21;ln([px-2,py,px+2,py-.5],C.stripe,1.1);}c.restore();}\r\n if(C.fluffy)fringe([[-8.5,-27.5,Math.PI-.6,5,5],[-10,-25,Math.PI-.4,4.6,4.6],[8.5,-27.5,.6,5,5],[10,-25,.4,4.6,4.6]],C.base);\r\n collar(0,-26.4,6.6,C,false);\r\n const hd=()=>{c.beginPath();c.moveTo(-11,-37);c.lineTo(-12.8,-47.4);c.quadraticCurveTo(-12.4,-49.2,-10.6,-48.2);c.lineTo(-4.6,-43.6);c.quadraticCurveTo(0,-45.2,4.6,-43.6);c.lineTo(10.6,-48.2);c.quadraticCurveTo(12.4,-49.2,12.8,-47.4);c.lineTo(11,-37);c.bezierCurveTo(13.2,-33,12.4,-28.8,8.6,-27.4);c.bezierCurveTo(4.5,-26.2,-4.5,-26.2,-8.6,-27.4);c.bezierCurveTo(-12.4,-28.8,-13.2,-33,-11,-37);c.closePath();};\r\n hd();c.fillStyle=C.base;c.fill();\r\n inside(hd,()=>{soft(0,-42,9,C.light,.6);soft(0,-28,10,C.dark,.35);if(K){soft(-8,-41,7,K.o,1);soft(8,-40,6,K.k,1);}\r\n  if(C.stripe){for(const [a,b] of [[-2.6,-43],[0,-43.6],[2.6,-43]])ln([a,b,a*.8,b+5],C.stripe,1.1);curve(-7,-33,0,-35,7,-33,C.stripe,1);curve(-6.5,-30,0,-31.6,6.5,-30,C.stripe,1);}\r\n  for(const sx of [-1,1])soft(sx*10.5,-45,3,C.dark,.5);if(C.points)for(const sx of [-1,1])soft(sx*11,-46,4.6,C.points,.85);});\r\n edge(hd);\r\n c.restore();}\r\n\r\n// walking, side on, facing right (flip: -1 faces left). ph = walk phase; ph null = standing\r\nfunction catWalk(cx,x,y,s,C,o={}){c=cx;const flip=o.flip||1,walking=o.ph!=null,ph=o.ph||0,t=o.t||0,K=C.calico;c.save();c.translate(x,y);c.scale(s*flip,s);c.lineJoin='round';c.lineCap='round';\r\n ell(0,.4,20,2.6,0,'rgba(60,30,10,.22)');\r\n const bob=walking?-Math.abs(Math.cos(ph))*.9:0;\r\n // a leg: thigh/shoulder pivot, swinging; the paw lifts while it swings forward\r\n const leg=(px,py,phase,front,far)=>{const a=walking?Math.sin(phase)*.42:0,lift=walking?Math.max(0,Math.cos(phase))*2.3:0,L=-py+bob;\r\n  const kx=px+Math.sin(a)*L*.55+(front?.6:-1.2)*lift*.6,ky=py+L*.55-lift*.5,fx=px+Math.sin(a)*L*.95+(front?1.4:.6)*lift*.4,fy=-lift*.55;\r\n  const col=far?shade(C.darkCoat?C.base:C.base,C.darkCoat?-.2:-.18):C.base,w=front?3.3:3.9;\r\n  const top=front?4.2:6.2,kn=front?2.9:2.7,ank=front?2.5:2.3;limb(px,py,kx,ky,top,kn,col);limb(kx,ky,fx,fy-1,kn,ank,C.tux&&!far?C.belly:col);\r\n  if(K&&!front&&!far)limb(px,py,kx,ky,top-1,kn-.6,K.o,false);\r\n  ell(fx+.9,fy-1,2.5,1.5,0,far?col:(C.belly||C.base));c.beginPath();c.ellipse(fx+.9,fy-1,2.5,1.5,0,0,7);c.lineWidth=.5;c.strokeStyle=EDGE;c.stroke();};\r\n c.save();c.translate(0,bob);\r\n // far legs, tail, then the body, near legs and head\r\n leg(-11.5,-11,ph+Math.PI,false,true);leg(7.5,-10.5,ph,true,true);\r\n const sw=Math.sin(t*2.2)*1.6+(walking?Math.sin(ph*.5)*1.2:0),TP=C.floof?[-17,-15,-28,-19+sw*.3,-23+sw,-32]:[-15.5,-14.5,-25,-18+sw*.3,-21+sw,-30.5];tailDraw(TP,C.floof?7:4.2,C.floof?5.6:3,C,K);tubeEdge(TP,4.2,3);\r\n if(C.stripe){c.save();c.globalAlpha=.65;for(const u of [.35,.58,.8]){const a=(1-u)*(1-u),b=2*u*(1-u),d=u*u,qx=a*-15.5+b*-25+d*(-21+sw),qy=a*-14.5+b*(-18+sw*.3)+d*-30.5;ln([qx-1.9,qy+.6,qx+1.9,qy-.6],C.stripe,1.1);}c.restore();}\r\n const body=C.floof?()=>{c.beginPath();c.moveTo(-15,-19.2);c.bezierCurveTo(-8,-22.2,4,-22.4,9.5,-20.4);c.bezierCurveTo(14,-19,15.6,-14.5,15,-10.8);c.bezierCurveTo(14.4,-7,11.5,-5.6,7.5,-6);\r\n  c.bezierCurveTo(2,-6.6,-6,-6.6,-11,-6.6);c.bezierCurveTo(-16.5,-6.6,-19.4,-10.5,-19.4,-13.8);c.bezierCurveTo(-19.4,-16.6,-17.6,-18.6,-15,-19.2);c.closePath();}\r\n  :()=>{c.beginPath();c.moveTo(-14,-17.6);c.bezierCurveTo(-8,-20.4,3.5,-20.4,8.5,-18.6);c.bezierCurveTo(12,-17.6,13.4,-14.5,13.2,-11.6);c.bezierCurveTo(13,-8.6,10.5,-7.4,7.5,-7.8);\r\n  c.bezierCurveTo(2,-8.6,-6,-8.4,-10.5,-8.2);c.bezierCurveTo(-15,-8,-17.4,-11,-17.4,-13.6);c.bezierCurveTo(-17.4,-15.8,-16.2,-17,-14,-17.6);c.closePath();};\r\n if(C.fluffy)fluffBody('walk',C);body();c.fillStyle=C.base;c.fill();\r\n inside(body,()=>{soft(-2,-19.5,14,C.light,.6);soft(0,-5,15,C.dark,.32);soft(-13,-12,6.5,C.dark,.3);soft(-12,-15,5,C.light,.35);\r\n  if(K){soft(-5,-17,8,K.o,1);soft(-14,-15,5,K.k,1);soft(6,-17.5,4,K.k,.9);}\r\n  if(C.belly)soft(4,-8,9,C.belly,.9);\r\n  if(C.stripe){for(const sx of [-11,-6.5,-2,2.5]){curve(sx,-20,sx-1.6,-16,sx-.6,-12.4,C.stripe,1.3);}}});\r\n edge(body);\r\n leg(-13,-11.5,ph,false,false);leg(9,-10.5,ph+Math.PI,true,false);\r\n if(C.fluffy)fringe([[9.6,-15.6,Math.PI*.45,4.6,4.4],[11.4,-13.4,Math.PI*.4,4.4,4.2],[12.8,-11.2,Math.PI*.35,3.8,3.8],[8,-16.4,Math.PI*.55,4,4]],C.light);\r\n if(C.floof){const nk=()=>{c.beginPath();c.ellipse(11,-15.8,6.6,7.2,-.3,0,7);};nk();c.fillStyle=C.base;c.fill();inside(nk,()=>{soft2(13,-11,6.5,C.belly,1);});}\r\n // head, side on\r\n const hx=o.eat?3:0,hy=o.eat?5.5:0;c.save();c.translate(hx,hy);if(o.eat)c.rotate(.28);collar(11.2,-16.6,2.8,C,false);c.translate(10,-17);c.scale(1.22,1.22);c.translate(-10.6,17.4);\r\n // far ear behind\r\n c.beginPath();c.moveTo(15.4,-26.2);c.lineTo(17.6,-31);c.quadraticCurveTo(18.6,-31.6,18.9,-30.4);c.lineTo(19.6,-25.6);c.closePath();c.fillStyle=shade(C.darkCoat?C.base:C.base,-.15);c.fill();\r\n const hd=()=>{c.beginPath();c.moveTo(9.6,-17.2);c.bezierCurveTo(9,-21,10.2,-25.4,13.4,-26.4);c.lineTo(13.2,-31.2);c.quadraticCurveTo(13.5,-32.6,14.7,-31.9);c.lineTo(17.6,-27);\r\n  c.bezierCurveTo(20,-26.6,22,-24.6,22.6,-22);c.lineTo(23.7,-20.3);c.quadraticCurveTo(24.1,-19.2,23,-18.4);c.bezierCurveTo(21.4,-16.8,18.2,-15.4,15,-15.7);c.bezierCurveTo(12.6,-15.9,10.8,-16.3,9.6,-17.2);c.closePath();};\r\n if(C.fluffy)fringe([[10.6,-18.6,Math.PI*.82,4,4],[11.8,-16.4,Math.PI*.66,3.8,3.8],[10.2,-21,Math.PI*.9,3.4,3.6]],C.base);hd();c.fillStyle=C.base;c.fill();\r\n inside(hd,()=>{soft(15,-25,7,C.light,.75);soft(11,-17,6,C.dark,.35);if(K){soft(13,-27,6,K.o,1);}\r\n  if(C.points){soft(19.5,-21.5,5.5,C.points,.55);soft(14.4,-29,4,C.points,.85);}if(C.belly){soft(20.5,-17.6,4.6,C.belly,1);}if(C.tux)soft(21.4,-20.4,3.2,C.belly,.95);if(C.darkCoat&&!C.tux)soft(21,-19,3.5,C.light,.35);\r\n  c.beginPath();c.moveTo(14,-30.4);c.lineTo(14.2,-26.8);c.lineTo(16.6,-27.3);c.closePath();c.fillStyle=C.darkCoat?'#6a4450':'#f2a3b2';c.fill();\r\n  if(C.stripe){ln([15.5,-26.6,16.4,-23.6],C.stripe,1);ln([13.2,-25.4,14,-22.6],C.stripe,1);curve(11,-21,13,-20.2,15,-20.4,C.stripe,.9);}});\r\n edge(hd);\r\n eye(19.3,-22,2.2,2.5,C,{happy:o.happy,lid:o.eat?.7:(!o.happy&&((t*.7)%3.1)<.12?1:0)});\r\n ell(23.3,-19.7,1,.8,0,C.nose);\r\n const ink=C.darkCoat?'rgba(0,0,0,.85)':'rgba(60,34,20,.75)';curve(23,-18.9,22.4,-17.4,20.8,-17.5,ink,.5);\r\n if(o.chew){const m=Math.abs(Math.sin(o.chew*Math.PI*6));if(m>.25){c.beginPath();c.ellipse(21.6,-17,1.1,m*.6+.2,0,0,7);c.fillStyle='#b3485e';c.fill();}}\r\n for(const [dy,ey] of [[-.4,-1.6],[.4,.2],[1.1,1.8]])curve(21.4,-18.8+dy,25,-18.9+dy+ey*.4,28.6,-19+ey,WHISK(C),.35);\r\n c.restore();c.restore();c.restore();}\r\n\r\nreturn {COATS,catSit,catBack,catWalk};})();\r\nconst TREATS=['tuna','sardine','cheese','shrimp','biscuit'];\r\nconst COLS=CATART.COATS.map((A,i)=>({name:A.name,fur:A.base,collar:A.collar,rim:A.calico?[A.calico.o,A.base,A.calico.k]:null,treat:TREATS[i],art:A})); // one coat = one plate (rim = coat, inner ring = collar) = one treat\r\nconst SEATS=5,NEED=3,DIR=[[0,-1],[1,0],[0,1],[-1,0]];\r\nconst cv=document.getElementById('cv'),ctx=cv.getContext('2d');\r\nconst IMG={};let artReady=false;\r\nPromise.all(Object.entries(ART).map(([k,src])=>new Promise(res=>{const im=new Image();im.onload=()=>{IMG[k]=im;res();};im.onerror=res;im.src=src;}))).then(()=>{artReady=true;});\r\n\r\n// ---------- layout ----------\r\nlet scale=1,offX=0,H=800,dpr=1,L={};\r\nfunction resize(){\r\n dpr=Math.min(3,window.devicePixelRatio||1);const vw=innerWidth,vh=innerHeight;\r\n scale=Math.min(vw/W,vh/600);offX=(vw-W*scale)/2;H=vh/scale;\r\n cv.width=Math.round(vw*dpr);cv.height=Math.round(vh*dpr);\r\n const top=8,belt={x:10,y:top+104,w:380,h:62};\r\n const counter={y:belt.y+belt.h,h:22},seatY=counter.y+counter.h+40;\r\n const roomTop=seatY+56,bottom=H-50;\r\n const b=game?BOARDS[game.index]:BOARDS[0];\r\n const cell=Math.floor(Math.min((W-28)/b.cols,(bottom-roomTop-14)/b.rows));\r\n const rw=cell*b.cols,rh=cell*b.rows;\r\n L={top,belt,counter,seatY,cell,room:{x:(W-rw)/2,y:roomTop+Math.max(0,(bottom-roomTop-14-rh)/2)+7,w:rw,h:rh},bottom,\r\n  seatX:i=>W/2+(i-2)*76,nextX:belt.x+38};\r\n makeStars();}\r\nlet stars=[];\r\nfunction makeStars(){stars=[];let s=7;const r=()=>(s=s*16807%2147483647)/2147483647;for(let i=0;i<110;i++)stars.push({x:r(),y:r(),r:.5+r()*1.6,p:r()*6.3,s:.6+r()*1.6});}\r\n\r\n// ---------- sound (tiny synth blips; muteable) ----------\r\nlet AC=null,muted=false;try{muted=localStorage.getItem('catjam.muted')==='1';}catch(e){}\r\nfunction snd(kind){if(muted)return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();const t=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();o.connect(g);g.connect(AC.destination);\r\n const S={tap:[520,780,.08,'triangle',.12],bonk:[180,120,.12,'square',.07],seat:[660,990,.1,'sine',.12],plate:[880,880,.05,'triangle',.06],nom:[300,420,.06,'sine',.1],happy:[700,1400,.22,'triangle',.12],win:[523,1046,.5,'triangle',.14],lose:[300,140,.5,'sawtooth',.06],click:[600,600,.04,'square',.04]}[kind];\r\n if(!S)return;o.type=S[3];o.frequency.setValueAtTime(S[0],t);o.frequency.exponentialRampToValueAtTime(S[1],t+S[2]);g.gain.setValueAtTime(S[4],t);g.gain.exponentialRampToValueAtTime(.001,t+S[2]+.05);o.start(t);o.stop(t+S[2]+.06);}catch(e){}}\r\n\r\n// ---------- game state ----------\r\nlet game=null,T=0;\r\nfunction todayIndex(){const d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/864e5)%BOARDS.length;}\r\nfunction startBoard(i){\r\n const b=BOARDS[i];game={index:i,b,cats:b.cats.map((c,id)=>({id,k:c.k,dir:c.d,c:c.c,r:c.r,st:'room',seat:-1,need:NEED,eaten:0,segs:[],face:'cat',bump:null,wob:-9,arrive:0,eatFree:0,nib:[],seatOrder:0})),\r\n  seats:Array(SEATS).fill(null),seatFree:Array(SEATS).fill(0),p:0,beltFree:0,shiftAt:-9,shifts:0,flying:[],events:[],result:null,resultAt:0,endAt:0,order:0,taps:0,hint:!window.__cjHinted&&(window.__cjHinted=true),fx:[]};\r\n resize();}\r\nfunction cellXY(c,r){return {x:L.room.x+(c+.5)*L.cell,y:L.room.y+(r+.5)*L.cell};}\r\nfunction alive(){return game.cats.filter(c=>c.st==='room');}\r\nfunction blocker(cat){const occ=new Map(alive().map(c=>[c.c+','+c.r,c]));const [dx,dy]=DIR[cat.dir];let x=cat.c+dx,y=cat.r+dy,n=1;\r\n while(x>=0&&y>=0&&x<game.b.cols&&y<game.b.rows){const o=occ.get(x+','+y);if(o)return {o,n};x+=dx;y+=dy;n++;}return null;}\r\nfunction at(t,fn){game.events.push({t,fn});game.endAt=Math.max(game.endAt,t);}\r\nfunction seg(cat,t0,dur,x1,y1,s1,arc=0){const last=pos(cat,t0);cat.segs.push({t0,t1:t0+dur,x0:last.x,y0:last.y,s0:last.s,x1,y1,s1,arc});game.endAt=Math.max(game.endAt,t0+dur);}\r\nfunction pos(cat,t){const S=cat.segs;if(!S.length){const p=cellXY(cat.c,cat.r);return {x:p.x,y:p.y,s:1};}\r\n let g=S[0];if(t<g.t0)return {x:g.x0,y:g.y0,s:g.s0};for(const q of S){if(t>=q.t0)g=q;}\r\n const u=Math.max(0,Math.min(1,(t-g.t0)/(g.t1-g.t0))),e=u<.5?2*u*u:1-Math.pow(-2*u+2,2)/2;\r\n return {x:g.x0+(g.x1-g.x0)*e,y:g.y0+(g.y1-g.y0)*e-g.arc*Math.sin(Math.PI*u),s:g.s0+(g.s1-g.s0)*e};}\r\nconst SEAT_S=()=>1.3*60/L.cell; // a seated cat at scale 1.3\r\n\r\nfunction tapCat(cat){\r\n if(game.result||cat.st!=='room')return;\r\n const bl=blocker(cat);\r\n if(bl){cat.bump={t:T,n:bl.n};bl.o.wob=T+.12;snd('bonk');game.fx.push({t:T,kind:'bonk',x:cellXY(bl.o.c,bl.o.r).x,y:cellXY(bl.o.c,bl.o.r).y});return;}\r\n // only a seat that is free on screen too (its last cat has gone), so cats never queue around the room\r\n const s=game.seats.findIndex((x,i)=>x===null&&game.seatFree[i]<=T+.3);if(s<0){cat.bump={t:T,n:1.2};snd('bonk');return;}\r\n snd('tap');game.taps++;\r\n cat.st='out';cat.seat=s;cat.seatOrder=++game.order;game.seats[s]=cat.id;\r\n // out of the room along its arrow, then a hop to its seat\r\n const p=cellXY(cat.c,cat.r),[dx,dy]=DIR[cat.dir],R=L.room;\r\n let ex=p.x,ey=p.y;if(dx>0)ex=R.x+R.w+L.cell*.55;if(dx<0)ex=R.x-L.cell*.55;if(dy>0)ey=R.y+R.h+L.cell*.55;if(dy<0)ey=R.y-L.cell*.15;\r\n const d=Math.hypot(ex-p.x,ey-p.y),t1=T+.05+d/1000;\r\n seg(cat,T,t1-T,ex,ey,dy<0?.9:1);\r\n const go=Math.max(t1,game.seatFree[s]);game.seatFree[s]=1e9;\r\n seg(cat,go,.45,L.seatX(s),L.seatY,SEAT_S(),70);cat.arrive=go+.45;cat.eatFree=cat.arrive;\r\n at(cat.arrive,()=>{cat.st='seat';snd('seat');game.fx.push({t:T,kind:'land',x:L.seatX(s),y:L.seatY+30,k:cat.k});});\r\n settle();\r\n const left=alive().length;\r\n if(!left&&game.seats.every(x=>x===null))finish('win');\r\n else if(game.seats.every(x=>x!==null)&&!match())finish('lose');}\r\nfunction match(){if(game.p>=game.b.plates.length)return null;const k=game.b.plates[game.p];let best=null;\r\n for(const id of game.seats){if(id===null)continue;const c=game.cats[id];if(c.k===k&&c.need>0&&(!best||c.seatOrder<best.seatOrder))best=c;}return best;}\r\nfunction settle(){let c;\r\n while((c=match())){const pi=game.p++,k=game.b.plates[pi];c.need--;\r\n  const P=Math.max(game.beltFree,c.eatFree-.32,c.arrive-.2,T);game.beltFree=P+.2;c.eatFree=P+.28+.45;\r\n  const cat=c,s=c.seat,last=c.need===0;\r\n  at(P,()=>{game.shiftAt=T;game.shifts=pi+1;game.flying.push({k,t0:T,s,pi});snd('plate');});\r\n  at(P+.28,()=>{cat.nib.push(T);snd('nom');});\r\n  at(P+.73,()=>{cat.eaten++;game.flying=game.flying.filter(f=>f.pi!==pi);});\r\n  if(last){game.seats[s]=null;const tl=c.eatFree+.08;\r\n   at(tl,()=>{cat.face='happy';snd('happy');for(let i=0;i<8;i++)game.fx.push({t:T,kind:'heart',x:L.seatX(s),y:L.seatY-10,a:i/8*6.28,k:cat.k});});\r\n   seg(cat,tl+.05,.18,L.seatX(s),L.seatY-26,SEAT_S()*1.08);\r\n   seg(cat,tl+.23,.16,L.seatX(s),L.seatY,SEAT_S());\r\n   const side=s<2?-1:s>2?1:(cat.id%2?1:-1);\r\n   seg(cat,tl+.42,.7,L.seatX(s)+side*270,L.seatY-30,SEAT_S()*.9,90);\r\n   at(tl+1.12,()=>{cat.st='gone';});game.seatFree[s]=tl+.55;}}}\r\nfunction finish(r){game.result=r;game.resultAt=Math.max(game.endAt,T)+(r==='win'?.35:.6);at(game.resultAt,()=>snd(r==='win'?'win':'lose'));}\r\nfunction update(dt){T+=dt;if(!game)return;game.events.sort((a,b)=>a.t-b.t);while(game.events.length&&game.events[0].t<=T){game.events.shift().fn();}\r\n game.fx=game.fx.filter(f=>T-f.t<1.2);}\r\n\r\n// ---------- drawing helpers ----------\r\nfunction rr(x,y,w,h,r,fill,stroke,lw){ctx.beginPath();ctx.roundRect?ctx.roundRect(x,y,w,h,r):ctx.rect(x,y,w,h);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.lineWidth=lw||2;ctx.strokeStyle=stroke;ctx.stroke();}}\r\nfunction circ(x,y,r,fill,stroke,lw){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.lineWidth=lw||2;ctx.strokeStyle=stroke;ctx.stroke();}}\r\nfunction bigText(t,x,y,size,fill,stroke,lw){ctx.save();ctx.font='900 '+size+'px Impact, \"Arial Black\", system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineJoin='round';ctx.lineWidth=lw||size/6;ctx.strokeStyle=stroke;ctx.strokeText(t,x,y);ctx.fillStyle=fill;ctx.fillText(t,x,y);ctx.restore();}\r\nfunction label(t,x,y,size,color,align='center',weight=700){ctx.font=weight+' '+size+'px system-ui, -apple-system, \"Segoe UI\", sans-serif';ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;ctx.fillText(t,x,y);}\r\nfunction pill(b,text,fill,dark,size=15,on=true){ctx.save();ctx.globalAlpha=on?1:.4;rr(b.x,b.y+3,b.w,b.h,b.h/2,dark);rr(b.x,b.y,b.w,b.h,b.h/2,fill,'#fff',2.5);\r\n rr(b.x+6,b.y+4,b.w-12,b.h*.32,b.h*.16,'rgba(255,255,255,.28)');bigText(text,b.x+b.w/2,b.y+b.h/2+1,size,'#fff',dark,4);ctx.restore();}\r\nfunction roundBtn(b,draw,fill,dark,on=true){ctx.save();ctx.globalAlpha=on?1:.35;circ(b.x,b.y+3,b.r,dark);circ(b.x,b.y,b.r,fill,'#fff',2.5);ctx.beginPath();ctx.ellipse(b.x,b.y-b.r*.45,b.r*.6,b.r*.28,0,0,7);ctx.fillStyle='rgba(255,255,255,.3)';ctx.fill();\r\n ctx.translate(b.x,b.y);ctx.strokeStyle='#fff';ctx.fillStyle='#fff';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';draw(b.r);ctx.restore();}\r\n// cats sitting still in the room are drawn once per coat, pose and size, then reused (28 detailed cats live cost ~16 ms a frame)\r\nconst SPR=new Map();\r\nfunction sprite(C,view,k){const sc=scale*dpr,key=C.name+view+Math.round(k*100)+'@'+sc.toFixed(2);let S=SPR.get(key);if(S)return S;\r\n const w=Math.ceil(72*k*sc),h=Math.ceil(62*k*sc),cv=document.createElement('canvas');cv.width=w;cv.height=h;const g=cv.getContext('2d'),ox=w/2,oy=h-6*k*sc;\r\n const A=C.art;if(view==='front')CATART.catSit(g,ox,oy,k*sc,A,{t:1});else if(view==='back')CATART.catBack(g,ox,oy,k*sc,A,{t:1});else CATART.catWalk(g,ox,oy,k*sc,A,{flip:view==='left'?-1:1,ph:null,t:1});\r\n S={cv,w:w/sc,h:h/sc,ox:ox/sc,oy:oy/sc};SPR.set(key,S);return S;}\r\nfunction kitten(x,y,s,C,view,o={}){if(o.still){const S=sprite(C,view,s);ctx.drawImage(S.cv,x-S.ox,y-S.oy,S.w,S.h);return;}const A=C.art,k=s*1.0,eat=o.dip?Math.min(1,-o.dip/5*1.3):0,chew=((o.t||0)*2.4)%1;\r\n if(view==='front')CATART.catSit(ctx,x,y,k,A,{t:o.t||0,happy:o.happy,eat,chew:eat>0?chew:0});\r\n else if(view==='back')CATART.catBack(ctx,x,y,k,A,{t:o.t||0});\r\n else CATART.catWalk(ctx,x,y,k,A,{flip:view==='left'?-1:1,ph:o.walk!=null?o.walk*.6:null,t:o.t||0,happy:o.happy});}\r\nfunction plate(k,x,y,r){const C=COLS[k];circ(x,y+r*.12,r,'rgba(0,0,0,.35)');\r\n if(C.rim){for(let i=0;i<6;i++){ctx.beginPath();ctx.moveTo(x,y);ctx.arc(x,y,r,i*Math.PI/3-.4,(i+1)*Math.PI/3-.4);ctx.closePath();ctx.fillStyle=C.rim[i%3];ctx.fill();}}else circ(x,y,r,C.fur);\r\n circ(x,y,r,null,'#fff',Math.max(1.5,r*.07));circ(x,y,r*.7,'#fff8ec',C.collar,Math.max(2.5,r*.14));\r\n const im=IMG[C.treat];if(im){const sc=r*1.12/Math.max(im.width,im.height);ctx.drawImage(im,x-im.width*sc/2,y-im.height*sc/2,im.width*sc,im.height*sc);}}\r\nfunction arrowGlyph(d,r){ctx.save();ctx.rotate(d*Math.PI/2);ctx.beginPath();ctx.moveTo(-r*.5,r*.18);ctx.lineTo(0,-r*.38);ctx.lineTo(r*.5,r*.18);ctx.stroke();ctx.restore();}\r\n\r\n// ---------- draw ----------\r\nfunction drawBg(){const g=ctx.createLinearGradient(0,0,0,cv.height);g.addColorStop(0,'#1b1036');g.addColorStop(.6,'#24124a');g.addColorStop(1,'#140b26');ctx.fillStyle=g;ctx.fillRect(0,0,cv.width,cv.height);\r\n for(const s of stars){ctx.globalAlpha=.35+.65*Math.abs(Math.sin(T*s.s+s.p));circ(s.x*cv.width,s.y*cv.height,s.r*dpr,'#fff');}ctx.globalAlpha=1;}\r\nfunction buttons(){const t=L.top;return {\r\n restart:{x:W-28,y:t+24,r:20},mute:{x:W-74,y:t+24,r:20},\r\n prev:{x:30,y:t+74,r:18},next:{x:W-30,y:t+74,r:18},board:{x:56,y:t+58,w:W-112,h:32},\r\n again:{x:W/2-140,y:0,w:132,h:50},go:{x:W/2+8,y:0,w:132,h:50}};}\r\nfunction drawHeader(){const B=buttons(),t=L.top;\r\n bigText('CAT JAM',18+70,t+22,34,'#ffd23f','#3a1a00',8);label('DAILY PUZZLE',20,t+46,10,'rgba(255,255,255,.55)','left',800);\r\n roundBtn(B.restart,r=>{ctx.beginPath();ctx.arc(0,0,r*.42,-.3,4.6);ctx.stroke();ctx.beginPath();ctx.moveTo(r*.4,-r*.62);ctx.lineTo(r*.42,-r*.12);ctx.lineTo(-r*.05,-r*.2);ctx.stroke();},'#ff8a3a','#8a3a0a');\r\n roundBtn(B.mute,r=>{ctx.beginPath();ctx.moveTo(-r*.45,-r*.15);ctx.lineTo(-r*.2,-r*.15);ctx.lineTo(r*.1,-r*.42);ctx.lineTo(r*.1,r*.42);ctx.lineTo(-r*.2,r*.15);ctx.lineTo(-r*.45,r*.15);ctx.closePath();ctx.fill();\r\n  if(muted){ctx.beginPath();ctx.moveTo(-r*.55,-r*.55);ctx.lineTo(r*.55,r*.55);ctx.strokeStyle='#ff5a6e';ctx.stroke();}else{ctx.lineWidth=3;ctx.beginPath();ctx.arc(r*.12,0,r*.42,-.8,.8);ctx.stroke();}},'#6a5aa8','#2a1f5a');\r\n const bd=B.board;rr(bd.x,bd.y,bd.w,bd.h,bd.h/2,'rgba(0,0,0,.35)','rgba(255,255,255,.25)',1.5);\r\n const today=game.index===todayIndex();\r\n bigText((game.index+1)+'/'+BOARDS.length+' \u00b7 '+game.b.name.toUpperCase(),W/2,bd.y+bd.h/2+1,17,'#fff','#2a1650',4);\r\n if(today){rr(bd.x+bd.w-62,bd.y-9,56,18,9,'#7ad65a','#fff',1.5);label('TODAY',bd.x+bd.w-34,bd.y,10,'#0c3a12','center',900);}\r\n roundBtn(B.prev,r=>arrowGlyph(3,r),'#4fa8ff','#14508f');roundBtn(B.next,r=>arrowGlyph(1,r),'#4fa8ff','#14508f');}\r\nfunction drawBelt(){const B=L.belt,plates=game.b.plates;\r\n rr(B.x,B.y,B.w,B.h,14,'#3a2a1a','#1a1008',3); // frame\r\n rr(B.x+6,B.y+8,B.w-12,B.h-16,10,'#2c2840');\r\n // rolling belt: chevrons slide left while the belt moves\r\n const sh=Math.max(0,1-(T-game.shiftAt)/.2),move=game.shifts-sh;ctx.save();ctx.beginPath();ctx.rect(B.x+6,B.y+8,B.w-12,B.h-16);ctx.clip();\r\n ctx.strokeStyle='rgba(255,255,255,.08)';ctx.lineWidth=6;const off=-(move*52)%26;\r\n for(let x=B.x+off-26;x<B.x+B.w+26;x+=26){ctx.beginPath();ctx.moveTo(x+8,B.y+10);ctx.lineTo(x,B.y+B.h/2);ctx.lineTo(x+8,B.y+B.h-10);ctx.stroke();}\r\n ctx.fillStyle='rgba(0,0,0,.25)';ctx.fillRect(B.x+6,B.y+8,B.w-12,4);ctx.fillRect(B.x+6,B.y+B.h-12,B.w-12,4);\r\n // the hatch at the left: the next plate waits under a gold arch\r\n const vis=7;let first=game.shifts;\r\n for(let j=Math.min(plates.length-1,first+vis);j>=first;j--){const slot=j-move,x=L.nextX+slot*50;if(x>B.x+B.w-20)continue;plate(plates[j],x,B.y+B.h/2,slot<.5?24:20);}\r\n ctx.restore();\r\n const left=plates.length-game.shifts;\r\n if(left>0){ctx.save();ctx.globalAlpha=.9+.1*Math.sin(T*5);ctx.lineWidth=3;ctx.strokeStyle='#ffd23f';ctx.beginPath();ctx.arc(L.nextX,B.y+B.h/2,29,0,7);ctx.stroke();ctx.restore();\r\n  rr(L.nextX-22,B.y-9,44,16,8,'#ffd23f','#3a1a00',1.5);label('NEXT',L.nextX,B.y-1,10,'#3a1a00','center',900);}\r\n rr(B.x+B.w-58,B.y-9,52,16,8,'rgba(20,10,30,.9)','rgba(255,255,255,.4)',1);label(left+' left',B.x+B.w-32,B.y-1,10,'#fff','center',800);}\r\nfunction drawCounter(){const C=L.counter;\r\n let g=ctx.createLinearGradient(0,C.y,0,C.y+C.h);g.addColorStop(0,'#d39a5c');g.addColorStop(.55,'#b47a42');g.addColorStop(1,'#7e4f28');ctx.fillStyle=g;rr(8,C.y,384,C.h,6);ctx.fill();\r\n ctx.fillStyle='rgba(255,236,200,.35)';ctx.fillRect(12,C.y+1.5,376,2);ctx.fillStyle='rgba(40,18,4,.45)';ctx.fillRect(8,C.y+C.h-3,384,3);\r\n for(let i=0;i<SEATS;i++){const x=L.seatX(i),y=L.seatY;\r\n  ctx.beginPath();ctx.ellipse(x+3,y+52,20,4.5,0,0,7);ctx.fillStyle='rgba(0,0,0,.35)';ctx.fill(); // stool shadow\r\n  g=ctx.createLinearGradient(x-4,0,x+4,0);g.addColorStop(0,'#3a2412');g.addColorStop(.5,'#7a4f2a');g.addColorStop(1,'#3a2412');ctx.fillStyle=g;ctx.fillRect(x-3.5,y+28,7,23);\r\n  ctx.fillStyle='#5a3a1e';ctx.beginPath();ctx.ellipse(x,y+44,11,3,0,0,7);ctx.fill();\r\n  ctx.beginPath();ctx.ellipse(x,y+29,29,9.5,0,0,7);ctx.fillStyle='#7a2a24';ctx.fill();\r\n  g=ctx.createRadialGradient(x-8,y+22,2,x,y+26,30);g.addColorStop(0,'#ef7a68');g.addColorStop(.6,'#c8473c');g.addColorStop(1,'#93302a');ctx.beginPath();ctx.ellipse(x,y+26,29,9.5,0,0,7);ctx.fillStyle=g;ctx.fill();\r\n  const id=game.seats[i];if(id===null&&game.seatFree[i]<=T){label('free',x,y+6,11,'rgba(255,255,255,.4)','center',800);}}}\r\nfunction drawCat(cat){if(cat.st==='gone')return;const p=pos(cat,T),q=pos(cat,T+.03);let x=p.x,y=p.y;const s=p.s,inRoom=cat.st==='room',C=COLS[cat.k],ks=L.cell/60*s;\r\n if(cat.bump){const u=(T-cat.bump.t)/.28;if(u>=1)cat.bump=null;else{const [dx,dy]=DIR[cat.dir],a=Math.sin(Math.PI*u)*Math.min(L.cell*.28,(cat.bump.n-.82)*L.cell);x+=dx*a;y+=dy*a;}}\r\n let wob=0;if(T-cat.wob>=0&&T-cat.wob<.35)wob=Math.sin((T-cat.wob)*40)*(1-(T-cat.wob)/.35)*.14;\r\n let dip=0;for(const n of cat.nib){const u=(T-n)/.42;if(u>=0&&u<1)dip=Math.abs(Math.sin(u*Math.PI*3))*-5;} // nibble\r\n const vx=q.x-p.x,vy=q.y-p.y,moving=Math.hypot(vx,vy)>.35;\r\n let view=['back','right','front','left'][cat.dir];\r\n if(moving)view=Math.abs(vx)>Math.abs(vy)*.5?(vx>0?'right':'left'):(vy<0?'back':'front');\r\n else if(!inRoom&&!(cat.st==='out'&&T<cat.arrive-.3))view='front';\r\n const feet=y+.3*L.cell*s;\r\n ctx.save();ctx.translate(x,feet);ctx.rotate(wob);\r\n ctx.beginPath();ctx.ellipse(1.5*ks,1*ks,18*ks,5.5*ks,0,0,7);ctx.fillStyle='rgba(30,12,0,.32)';ctx.fill(); // contact shadow, a touch to the lower right (the light is top left)\r\n if(inRoom)kitten(0,0,ks,C,view,{t:T+cat.id*.7,still:true}); // the way it faces is the way it will walk: up = back to you, down = facing you, left/right = side on\r\n else kitten(0,0,ks,C,view,{walk:moving?T*17+cat.id:null,happy:cat.face==='happy',dip,t:T+cat.id*.7,mouth:dip<-1});\r\n ctx.restore();\r\n if(cat.seat>=0&&(cat.st==='seat'||(cat.st==='out'&&T>=cat.arrive))&&cat.face!=='happy'){ // 3 plate pips under the stool\r\n  for(let i=0;i<NEED;i++)circ(L.seatX(cat.seat)+(i-1)*13,L.seatY+44,5,i<cat.eaten?C.collar:'rgba(255,255,255,.18)',i<cat.eaten?'#fff':null,1.5);}}\r\nfunction drawFlying(){for(const f of game.flying){const u=Math.min(1,(T-f.t0)/.28),e=1-Math.pow(1-u,3),x0=L.nextX,y0=L.belt.y+L.belt.h/2,x1=L.seatX(f.s),y1=L.counter.y+L.counter.h/2+2;\r\n const x=x0+(x1-x0)*e,y=y0+(y1-y0)*e-30*Math.sin(Math.PI*u);const cat=game.cats.find(c=>c.seat===f.s&&c.st!=='gone'&&c.face!=='happy');\r\n let r=17;if(u>=1&&cat){const n=cat.nib.length?cat.nib[cat.nib.length-1]:T;const v=Math.max(0,Math.min(1,(T-n)/.45));r=17*(1-.25*v);ctx.globalAlpha=1-Math.max(0,v-.75)*4;}\r\n plate(f.k,x,y,r);ctx.globalAlpha=1;}}\r\nlet FLOOR=null;\r\nfunction floorPic(){const R=L.room,sc=scale*dpr,key=[R.x,R.y,R.w,R.h,sc].join(',');if(FLOOR&&FLOOR.key===key)return FLOOR;\r\n const A={x:R.x-16,y:R.y-20,w:R.w+32,h:R.h+36},cv=document.createElement('canvas');cv.width=Math.ceil(A.w*sc);cv.height=Math.ceil(A.h*sc);const g=cv.getContext('2d');g.scale(sc,sc);g.translate(-A.x,-A.y);\r\n const rnd=(n=>()=>(n=n*16807%2147483647)/2147483647)(7);const path=(x,y,w,h,r)=>{g.beginPath();g.roundRect?g.roundRect(x,y,w,h,r):g.rect(x,y,w,h);};\r\n g.save();path(A.x,A.y,A.w,A.h,24);g.clip();\r\n // floorboards: warm honey wood, staggered joints, a little grain\r\n const PH=15,tones=['#a3713f','#956637','#ab7a47','#8f6033','#9d6c3b'];\r\n for(let r=0,y=A.y;y<A.y+A.h;r++,y+=PH){g.fillStyle=tones[r%tones.length];g.fillRect(A.x,y,A.w,PH);\r\n  g.strokeStyle='rgba(255,226,180,.10)';g.lineWidth=1;g.beginPath();g.moveTo(A.x,y+1.5);g.lineTo(A.x+A.w,y+1.5);g.stroke();\r\n  g.globalAlpha=.10;g.strokeStyle='#4a2a10';for(let k=0;k<3;k++){const yy=y+3+rnd()*(PH-6);g.beginPath();g.moveTo(A.x,yy);for(let x=A.x;x<=A.x+A.w;x+=20)g.lineTo(x,yy+Math.sin(x*.05+r)*1.2);g.lineWidth=.8;g.stroke();}g.globalAlpha=1;\r\n  g.fillStyle='rgba(45,22,6,.5)';g.fillRect(A.x,y+PH-1,A.w,1);\r\n  for(let x=A.x+((r*67)%110)-40;x<A.x+A.w;x+=110+((r*13)%30)){g.fillRect(x,y,1,PH-1);}}\r\n // the rug under the cats: soft teal with a cream border, rounded, its edge lifting off the floor\r\n const rx=R.x+4,ry=R.y+2,rw=R.w-8,rh=R.h-4;\r\n g.fillStyle='rgba(30,12,0,.35)';path(rx+2,ry+4,rw,rh,18);g.fill();\r\n const rg=g.createLinearGradient(0,ry,0,ry+rh);rg.addColorStop(0,'#4d8486');rg.addColorStop(1,'#3a6a6c');g.fillStyle=rg;path(rx,ry,rw,rh,18);g.fill();\r\n g.strokeStyle='#efdcb2';g.lineWidth=3.5;path(rx+6,ry+6,rw-12,rh-12,13);g.stroke();g.strokeStyle='#c96b4a';g.lineWidth=1.4;path(rx+10.5,ry+10.5,rw-21,rh-21,10);g.stroke();\r\n g.save();path(rx+12,ry+12,rw-24,rh-24,9);g.clip();g.strokeStyle='rgba(255,255,255,.06)';g.lineWidth=1;for(let d=-rh;d<rw;d+=18){g.beginPath();g.moveTo(rx+d,ry);g.lineTo(rx+d+rh,ry+rh);g.moveTo(rx+d+rh,ry);g.lineTo(rx+d,ry+rh);g.stroke();}g.restore();\r\n g.strokeStyle='rgba(20,40,40,.55)';g.lineWidth=1.5;path(rx,ry,rw,rh,18);g.stroke();\r\n // window light from the top left, and a soft vignette\r\n let lg=g.createRadialGradient(A.x+A.w*.18,A.y-10,10,A.x+A.w*.18,A.y-10,A.w*1.1);lg.addColorStop(0,'rgba(255,214,150,.34)');lg.addColorStop(1,'rgba(255,214,150,0)');g.fillStyle=lg;g.fillRect(A.x,A.y,A.w,A.h);\r\n lg=g.createRadialGradient(A.x+A.w/2,A.y+A.h*.45,Math.min(A.w,A.h)*.35,A.x+A.w/2,A.y+A.h*.5,Math.max(A.w,A.h)*.75);lg.addColorStop(0,'rgba(20,8,0,0)');lg.addColorStop(1,'rgba(20,8,0,.5)');g.fillStyle=lg;g.fillRect(A.x,A.y,A.w,A.h);\r\n g.restore();\r\n g.lineWidth=5;g.strokeStyle='#3d220e';path(A.x+2.5,A.y+2.5,A.w-5,A.h-5,22);g.stroke();g.lineWidth=1.2;g.strokeStyle='rgba(255,220,170,.25)';path(A.x+5.5,A.y+5.5,A.w-11,A.h-11,19);g.stroke();\r\n FLOOR={key,cv,A};return FLOOR;}\r\nfunction drawRoom(){const F=floorPic(),R=L.room;\r\n // the sushi bar's back wall: warm dark wood behind the belt, counter and stools\r\n const wy=L.belt.y-16,wh=F.A.y-wy+24,wg=ctx.createLinearGradient(0,wy,0,wy+wh);wg.addColorStop(0,'#4a2c18');wg.addColorStop(1,'#2e1b0f');rr(4,wy,W-8,wh,18,wg,'rgba(255,220,170,.18)',1.5);\r\n ctx.save();ctx.beginPath();ctx.roundRect?ctx.roundRect(4,wy,W-8,wh,18):ctx.rect(4,wy,W-8,wh);ctx.clip();ctx.fillStyle='rgba(0,0,0,.18)';for(let x=20;x<W;x+=34)ctx.fillRect(x,wy,1.5,wh);\r\n const lg=ctx.createRadialGradient(W/2,L.seatY-10,10,W/2,L.seatY-10,230);lg.addColorStop(0,'rgba(255,200,120,.22)');lg.addColorStop(1,'rgba(255,200,120,0)');ctx.fillStyle=lg;ctx.fillRect(4,wy,W-8,wh);ctx.restore();\r\n ctx.drawImage(F.cv,F.A.x,F.A.y,F.A.w,F.A.h);\r\n}\r\nfunction drawFx(){for(const f of game.fx){const u=(T-f.t)/1.2;if(f.kind==='heart'){const d=u*70;ctx.save();ctx.globalAlpha=1-u;ctx.translate(f.x+Math.cos(f.a)*d,f.y+Math.sin(f.a)*d*.6-u*30);ctx.scale(.7,.7);heart(COLS[f.k].collar);ctx.restore();}\r\n else if(f.kind==='land'&&u<.4){ctx.save();ctx.globalAlpha=1-u/.4;ctx.beginPath();ctx.ellipse(f.x,f.y,30+u*80,8+u*20,0,0,7);ctx.strokeStyle=COLS[f.k].fill;ctx.lineWidth=3;ctx.stroke();ctx.restore();}\r\n else if(f.kind==='bonk'&&u<.5){ctx.save();ctx.globalAlpha=1-u*2;bigText('!',f.x+L.cell*.32,f.y-L.cell*.3-u*20,22,'#fff','#c02a2a',5);ctx.restore();}}}\r\nfunction heart(c){ctx.beginPath();ctx.moveTo(0,6);ctx.bezierCurveTo(-14,-4,-8,-16,0,-8);ctx.bezierCurveTo(8,-16,14,-4,0,6);ctx.fillStyle=c;ctx.fill();ctx.lineWidth=1.5;ctx.strokeStyle='#fff';ctx.stroke();}\r\nfunction drawStatus(){const y=L.bottom+22;if(game.result&&T>=game.resultAt)return;\r\n const k=game.shifts<game.b.plates.length?game.b.plates[game.shifts]:null;\r\n rr(14,y-18,W-28,36,18,'rgba(0,0,0,.35)','rgba(255,255,255,.15)',1.5);\r\n if(game.hint&&game.taps<3){label('A cat walks the way it faces (back turned = up)',W/2,y,13,'#ffe08a','center',800);return;}\r\n if(k===null){label('Everyone is fed',W/2,y,14,'#fff');return;}\r\n plate(k,40,y,13);const free=game.seats.filter((x,i)=>x===null&&game.seatFree[i]<=T).length;\r\n label('Next: '+COLS[k].name+' cat',60,y,14,'#fff','left',800);\r\n label(free+' seat'+(free===1?'':'s')+' free',W-28,y,13,free<=1?'#ff8a8a':'rgba(255,255,255,.75)','right',800);}\r\nfunction drawResult(){if(!game.result||T<game.resultAt)return;const u=Math.min(1,(T-game.resultAt)/.35),B=buttons(),win=game.result==='win';\r\n ctx.fillStyle='rgba(8,4,16,'+(.72*u)+')';ctx.fillRect(0,0,W,H);\r\n const cy=H*.42;ctx.save();ctx.translate(W/2,cy-70);const k=.6+.4*(1-Math.pow(1-u,3))+.04*Math.sin(T*5);ctx.scale(k,k);ctx.rotate(-.04);\r\n bigText(win?'ALL FED!':'JAMMED!',0,0,64,win?'#ffd23f':'#ff7a8a',win?'#3a1a00':'#4a0a14',10);ctx.restore();\r\n if(win){const ks=[...new Set(game.b.cats.map(c=>c.k))];ks.forEach((kk,i)=>{const x=W/2+(i-(ks.length-1)/2)*66,y=cy+40-Math.abs(Math.sin(T*6+i))*14;kitten(x,y,1.25,COLS[kk],'front',{happy:true,t:T+i});});\r\n  label(game.b.cats.length+' cats fed \u00b7 '+game.b.plates.length+' plates served',W/2,cy+62,15,'#fff');}\r\n else{const kk=game.b.plates[game.p];plate(kk,W/2,cy+8,30);label('All 5 seats are full and no '+COLS[kk].name.toLowerCase()+' cat is sitting.',W/2,cy+56,14,'#fff');label('Keep a seat free for the next plates.',W/2,cy+78,13,'rgba(255,255,255,.7)');}\r\n const by=cy+108;B.again.y=by;B.go.y=by;pill(B.again,win?'AGAIN':'TRY AGAIN','#ff8a3a','#8a3a0a',win?18:16);pill(B.go,'NEXT BOARD','#7ad65a','#1f5a1a',16);}\r\nfunction draw(){ctx.setTransform(1,0,0,1,0,0);drawBg();if(!game)return;\r\n ctx.setTransform(scale*dpr,0,0,scale*dpr,offX*dpr,0);\r\n drawHeader();drawRoom();drawBelt();drawCounter();\r\n const order=[...game.cats].sort((a,b)=>(a.st==='room')-(b.st==='room')?((a.st==='room')?-1:1):0);\r\n for(const c of game.cats)if(c.st==='room')drawCat(c);\r\n for(const c of game.cats)if(c.st!=='room')drawCat(c);\r\n drawFlying(); // the plate in front of the cat that eats from it\r\n drawFx();drawStatus();drawResult();\r\n if(!artReady)label('Loading\u2026',W/2,H/2,16,'#fff');}\r\n\r\n// ---------- input ----------\r\nfunction hitCircle(b,x,y){return Math.hypot(x-b.x,y-b.y)<=b.r+6;}\r\nfunction hitRect(b,x,y){return x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h;}\r\ncv.addEventListener('pointerdown',e=>{if(!game)return;const x=(e.clientX-offX)/scale,y=e.clientY/scale,B=buttons();\r\n if(game.result&&T>=game.resultAt){if(hitRect(B.again,x,y)){snd('click');startBoard(game.index);}else if(hitRect(B.go,x,y)){snd('click');startBoard((game.index+1)%BOARDS.length);}return;}\r\n if(hitCircle(B.restart,x,y)){snd('click');startBoard(game.index);return;}\r\n if(hitCircle(B.mute,x,y)){muted=!muted;try{localStorage.setItem('catjam.muted',muted?'1':'0');}catch(_){}snd('click');return;}\r\n if(hitCircle(B.prev,x,y)){snd('click');startBoard((game.index+BOARDS.length-1)%BOARDS.length);return;}\r\n if(hitCircle(B.next,x,y)){snd('click');startBoard((game.index+1)%BOARDS.length);return;}\r\n const R=L.room;if(x>=R.x&&y>=R.y&&x<R.x+R.w&&y<R.y+R.h){const c=Math.floor((x-R.x)/L.cell),r=Math.floor((y-R.y)/L.cell);const cat=game.cats.find(k=>k.st==='room'&&k.c===c&&k.r===r);if(cat)tapCat(cat);}});\r\naddEventListener('resize',()=>{resize();});\r\nlet last=performance.now();\r\nfunction frame(n){const dt=Math.min(.05,(n-last)/1000);last=n;update(dt);draw();requestAnimationFrame(frame);}\r\nstartBoard(todayIndex());requestAnimationFrame(frame);\r\n// test hook\r\nwindow.__catjam={get game(){return game;},get T(){return T;},startBoard,tapCat,blocker,cellXY,get L(){return L;},scale:()=>scale,offX:()=>offX};\r\n<\/script>\r\n<\/body>\r\n<\/html>\r\n";
CP87_LIST.push({id:'cat-jam',name:'Cat Jam',line:'Seat the cats at the sushi bar. Each one eats only plates of its colour.'});
